    },
    {
      "name": "store_code",
      "type": "VARCHAR",
      "description": "Receiving store."
    },
    {
      "name": "sku_code",
      "type": "VARCHAR",
      "description": "ERP item number."
    },
    {
      "name": "lot_no",
      "type": "VARCHAR",
      "description": "Supplier lot number."
    },
    {
      "name": "received_on",
      "type": "DATE",
      "description": "Date received."
    },
    {
      "name": "source_type",
      "type": "VARCHAR",
      "description": "purchase_order or transfer."
    },
    {
      "name": "source_doc",
      "type": "VARCHAR",
      "description": "Purchase order or transfer number."
    },
    {
      "name": "qty_base",
      "type": "INTEGER",
      "description": "Quantity received in base units."
    },
    {
      "name": "unit_cost_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Cost of one base unit, VND, VAT excluded."
    },
    {
      "name": "received_value_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Cost of the whole receipt, VAT excluded."
    }
  ]
}

{
  "query": "select * from marts.dim_store where store_code='NW014'"
}

{
  "query": "select (select sum(qty_base) from marts.fct_sales where store_code='NW014' and business_date between '2026-08-01' and '2026-08-31') sold, (select sum(qty_base) from marts.fct_goods_received where store_code='NW014' and received_on < '2026-08-01') recv_before, (select sum(qty_base) from marts.fct_goods_received where store_code='NW014' and received_on between '2026-08-01' and '2026-08-31') recv_aug, (select sum(qty_base) from marts.fct_sales where store_code='NW014' and business_date < '2026-08-01') sold_before, (select sum(qty_base) from marts.fct_transfers) t"
}

{
  "table": "marts.fct_transfers"
}

{
  "table": "marts.fct_transfers",
  "columns": [
    {
      "name": "transfer_no",
      "type": "VARCHAR",
      "description": "ERP transfer number."
    },
    {
      "name": "sku_code",
      "type": "VARCHAR",
      "description": "ERP item number."
    },
    {
      "name": "lot_no",
      "type": "VARCHAR",
      "description": "Lot being transferred."
    },
    {
      "name": "from_store_code",
      "type": "VARCHAR",
      "description": "Sending store. Its on-hand still holds the stock until delivery. The `store` entity of this model."
    },
    {
      "name": "to_store_code",
      "type": "VARCHAR",
      "description": "Receiving store."
    },
    {
      "name": "qty_base",
      "type": "INTEGER",
      "description": "Quantity in base units."
    },
    {
      "name": "transfer_status",
      "type": "VARCHAR",
      "description": "in_transit, delivered or cancelled."
    },
    {
      "name": "created_on",
      "type": "DATE",
      "description": "Date the transfer was created."
    },
    {
      "name": "shipped_on",
      "type": "DATE",
      "description": "Date the stock left the sending store. Set for cancelled transfers too."
    },
    {
      "name": "received_on",
      "type": "DATE",
      "description": "Date of delivery. Null unless delivered."
    },
    {
      "name": "updated_on",
      "type": "DATE",
      "description": "Date of the last status change."
    },
    {
      "name": "snapshot_date",
      "type": "DATE",
      "description": "Date the status refers to (the extract)."
    }
  ]
}

{
  "query": "select transfer_status, case when shipped_on<'2026-08-01' then 'before' when shipped_on<='2026-08-31' then 'aug' else 'after' end p, sum(qty_base) from marts.fct_transfers where from_store_code='NW014' group by 1,2"
}

{
  "value": 0.579,
  "replacement_metric": null,
  "caveats": [],
  "explanation": "The warehouse has no sell-through metric, so I calculated it as units sold in August 2026 divided by (opening stock at 1 Aug plus August receipts). NW014 sold 53,782 units. Opening stock was 43,891, which is receipts before August minus sales before August minus delivered transfers out. August receipts were 48,992. The result is 53,782 / 92,883 \u2248 0.579. This definition is my own assumption. I ignored returns, write-offs and the 840 units transferred out in August."
}
